/**
 * Manifest accessor for build-time code.
 *
 * Wraps `src/assets/image-manifest.json` (generated by
 * `src/scripts/generateImageManifest.ts`) so any consumer — runtime utilities,
 * rehype plugins, tests — can read image metadata synchronously, and without
 * caring whether the file exists yet.
 *
 * The manifest is loaded once per process, at module init. After regenerating it,
 * restart the dev server or rebuild the site.
 */

import type { ImageManifest, ImageManifestEntry } from '../scripts/lib/image-manifest';
import { lookupImageEntry } from '../scripts/lib/image-manifest';

/**
 * Load the manifest, tolerating a missing/corrupt file.
 *
 * The specifier is deliberately *relative*: this module is also reachable from
 * the rehype plugin, which `astro.config.mjs` loads outside Vite's module graph
 * (plain Node / esbuild config bundling), where tsconfig aliases such as
 * `@assets/…` do not resolve. A failure there used to be swallowed silently and
 * disabled every image placeholder, so it now warns instead.
 */
async function loadImageManifest(): Promise<ImageManifest | null> {
  try {
    const module = (await import('../assets/image-manifest.json')) as { default?: ImageManifest };
    const manifest = module.default ?? null;

    if (!manifest || typeof manifest.images !== 'object' || manifest.images === null) {
      console.warn('[image-manifest] src/assets/image-manifest.json has an unexpected shape. Run `pnpm generate:images`.');
      return null;
    }

    return manifest;
  } catch (error) {
    console.warn(
      `[image-manifest] failed to load src/assets/image-manifest.json (${(error as Error).message}). ` +
        'Run `pnpm generate:images`; image placeholders stay disabled until then.',
    );
    return null;
  }
}

/**
 * Resolved once at module init.
 *
 * A lazy load cannot work here: lookups are synchronous (component frontmatter,
 * the rehype transform), so the first caller in a process would always read an
 * empty cache and silently render without placeholders.
 */
const manifest: ImageManifest | null = await loadImageManifest();

/** The loaded manifest, or null when it is unavailable. */
export function getImageManifest(): ImageManifest | null {
  return manifest;
}

/**
 * Look up manifest metadata for an image reference.
 *
 * Accepts site-absolute paths (`/img/cover.webp`), legacy bare keys
 * (`img/cover.webp`), and remote URLs.
 */
export function getImageEntry(imagePath: string): ImageManifestEntry | null {
  return lookupImageEntry(manifest, imagePath);
}
